import { Injectable } from '@angular/core';
import { AngularFirestore } from '@angular/fire/compat/firestore';
import { map, Observable } from 'rxjs';
import { Diet } from '../diet-grid/diet.model';

@Injectable({
  providedIn: 'root',
})
export class DietsService {
  homeDietsOpen: string[] = ['Basic'];

  constructor(private fire: AngularFirestore) {}

  fetchDiet(id: string): Observable<Diet> {
    return this.fire
      .doc('/diets/' + id)
      .snapshotChanges()
      .pipe(
        map((dietData) => {
          return dietData.payload.data() as Diet;
        })
      );
  }

  fetchAllDiets(): Observable<Diet[]> {
    return this.fire
      .collection('diets')
      .get()
      .pipe(
        map((diets) => {
          return diets.docs.map((diet) => {
            return {
              id: diet.id,
              ...(<any>diet.data()),
            };
          });
        })
      );
  }

  fetchDietsByYear(year: number): Observable<Diet[]> {
    return this.fire
      .collection('diets', (ref) => ref.where('year', '==', year).orderBy('legacyId'))
      .get()
      .pipe(
        map((diets) => {
          return diets.docs.map((diet) => {
            return {
              id: diet.id,
              ...(<any>diet.data()),
            };
          });
        })
      );
  }
}
