import { Component, inject, OnDestroy, OnInit, signal } from '@angular/core';
import { AngularFireAuth } from '@angular/fire/compat/auth';

import { NzTabsModule } from 'ng-zorro-antd/tabs';
import { UserOutline, LockOutline, StepBackwardOutline } from '@ant-design/icons-angular/icons';
import { NzButtonModule } from 'ng-zorro-antd/button';
import { NzCheckboxModule } from 'ng-zorro-antd/checkbox';
import { NzFormModule, NzFormTooltipIcon } from 'ng-zorro-antd/form';
import { NzInputModule } from 'ng-zorro-antd/input';
import { NzSelectModule } from 'ng-zorro-antd/select';
import { NzDividerModule } from 'ng-zorro-antd/divider';
import { NzIconModule } from 'ng-zorro-antd/icon';

import { states } from '../../../assets/states';

import * as firebaseui from 'firebaseui';
import firebase from 'firebase/compat/app';
import EmailAuthProvider = firebase.auth.EmailAuthProvider;
import GoogleAuthProvider = firebase.auth.GoogleAuthProvider;
import { UsersService } from 'src/app/services/users.service';
import { NonNullableFormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { User } from '../user.model';
import { catchError, tap, throwError } from 'rxjs';

@Component({
  selector: 'login',
  standalone: true,
  imports: [
    ReactiveFormsModule,
    NzButtonModule,
    NzCheckboxModule,
    NzFormModule,
    NzInputModule,
    NzSelectModule,
    NzDividerModule,
    NzIconModule,
    NzTabsModule,
  ],
  templateUrl: './login.component.html',
  styleUrl: './login.component.scss',
})
export class LoginComponent implements OnInit, OnDestroy {
  ui: firebaseui.auth.AuthUI;
  private fb = inject(NonNullableFormBuilder);

  loading = signal<boolean>(false);
  signupWithGoogle = signal<boolean>(false);
  passwordReset = signal<boolean>(false);
  authMessage = '';

  signUpForm = this.fb.group({
    firstName: this.fb.control(''),
    lastName: this.fb.control(''),
    state: this.fb.control(''),
    email: this.fb.control('', Validators.required),
    password: this.fb.control('', [Validators.required, Validators.minLength(6)]),
    checkPassword: this.fb.control('', Validators.required),
    admin: this.fb.control(false),
    // country: this.fb.control(''),
    zipcode: this.fb.control('', [Validators.maxLength(5)]),
    // captcha: this.fb.control('', [Validators.required]),
    // agree: this.fb.control(false),
  });
  loginForm = this.fb.group({
    email: this.fb.control('', [Validators.required]),
    password: this.fb.control('', [Validators.required, Validators.minLength(6)]),
    remember: this.fb.control(true),
  });
  forgotPasswordForm = this.fb.group({
    email: this.fb.control('', [Validators.required]),
  });

  statesList = states;

  passwordVisible = false;
  captchaTooltipIcon: NzFormTooltipIcon = {
    type: 'info-circle',
    theme: 'twotone',
  };

  constructor(private fireAuth: AngularFireAuth, private usersSvc: UsersService) {}

  ngOnInit() {
    /* For Google Auth */
    // this.fireAuth.app.then((app) => {
    //   const uiConfig = {
    //     signInOptions: [EmailAuthProvider.PROVIDER_ID, GoogleAuthProvider.PROVIDER_ID],
    //     /* Login Successful */
    //     callbacks: {
    //       signInSuccessWithAuthResult: this.onLoginSuccessful.bind(this),
    //     },
    //   };
    //   this.ui = new firebaseui.auth.AuthUI(app.auth());
    //   this.ui.start('#firebaseui-auth-container', uiConfig);
    //   /* Force users to always have to sign in. Can remove or comment this out later */
    //   this.ui.disableAutoSignIn();
    // });
  }

  signIn() {
    this.loading.set(true);
    this.usersSvc
      .signInWithEmailAndPassword(this.loginForm.value.email, this.loginForm.value.password)
      .then((signInData) => {
        console.log('[LOGIN] Signed in', signInData);
        this.loading.set(false);
      });
  }

  confirmInvalid = () => this.signUpForm.value.checkPassword !== this.signUpForm.value.password;

  signUp() {
    this.loading.set(true);
    const fields = this.signUpForm.value;
    this.usersSvc
      .createUserWithEmailAndPassword(fields.email, fields.password)
      .then((newUserData) => {
        console.log('[LOGIN] Signed up ', newUserData);
        this.loading.set(false);
      });
    console.log('Create a siteUser too!', this.signUpForm.value);
    const newUser = {
      name: `${fields.firstName} ${fields.lastName}`,
      email: fields.email,
      admin: false,
      state: fields.state,
      zipcode: +fields.zipcode,
    };
    console.log('Inserting this user', newUser);
    this.usersSvc
      .addUser(newUser as User)
      .pipe(
        tap((user) => {
          console.log('New siteUser successfully created too', user);
          // Tell user success and can close modal!
        }),
        catchError((err) => {
          console.error('Failed to create siteUser');
          return throwError(() => err);
        })
      )
      .subscribe();
  }

  forgotPassword() {
    //const auth = getAuth();
    this.loading.set(true);
    const email = this.forgotPasswordForm.value.email;
    if (email.length > 6 && email.includes('@') && email.includes('.')) {
      this.usersSvc
        .sendResetPassword(email)
        .then(() => {
          this.authMessage = 'Email sent. Now please check your email and reset your password.';
        })
        .catch((error) => {
          this.authMessage = `${error.code} - ${error.message}`;
        })
        .finally(() => {
          this.passwordReset.set(true);
          this.loading.set(false);
        });
    }
  }

  signOut() {
    return this.usersSvc.signOut();
  }

  ngOnDestroy() {
    console.log('Destroying the login component');
    // this.ui.delete();
  }

  onLoginSuccessful(result) {
    /* Close the modal or redirect user to home */
    // this.router.navigateByUrl("/home")
  }
}
